using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Mvc.ApiExplorer;

namespace Fakeeh.MedicalKit.Api.Swagger;

/// <summary>
/// Content of the KIT integration Swagger document: folder order, descriptions and request / response examples,
/// taken from the Postman collection the Medical KIT team integrates against. The embedded kit-swagger.json is
/// generated by tools/generate-swagger-examples.js; regenerate it when the collection changes.
/// </summary>
public sealed class KitSwaggerContent
{
    private const string ResourceName = "Fakeeh.MedicalKit.Api.Swagger.kit-swagger.json";

    private KitSwaggerContent(JsonObject root)
    {
        Title = root["title"]!.GetValue<string>();
        Description = root["description"]!.GetValue<string>();
        Tags = root["tags"]!.AsArray()
            .Select(t => new KitTag(t!["name"]!.GetValue<string>(), t["description"]?.GetValue<string>()))
            .ToList();
        Operations = root["operations"]!.AsArray()
            .Select((o, index) => new KitOperation(o!.AsObject(), index))
            .ToList();
    }

    public static KitSwaggerContent Instance { get; } = Load();

    public string Title { get; }

    public string Description { get; }

    public IReadOnlyList<KitTag> Tags { get; }

    public IReadOnlyList<KitOperation> Operations { get; }

    /// <summary>The collection operation an API action implements, or null when the collection does not use it.</summary>
    public KitOperation? Find(ApiDescription api)
    {
        var method = api.HttpMethod ?? string.Empty;
        var template = "/" + (api.RelativePath ?? string.Empty).TrimEnd('/');
        return Operations.FirstOrDefault(o =>
            string.Equals(o.Method, method, StringComparison.OrdinalIgnoreCase) && PathMatches(template, o.Path));
    }

    /// <summary>Compares a route template (fhir/CodeSystem/{id}) with a concrete collection path (fhir/CodeSystem/medical-kit-vital-type).</summary>
    private static bool PathMatches(string template, string path)
    {
        var templateSegments = template.Split('/', StringSplitOptions.RemoveEmptyEntries);
        var pathSegments = path.Split('/', StringSplitOptions.RemoveEmptyEntries);
        return templateSegments.Length == pathSegments.Length
               && templateSegments.Zip(pathSegments).All(s =>
                   s.First.StartsWith('{') || string.Equals(s.First, s.Second, StringComparison.OrdinalIgnoreCase));
    }

    private static KitSwaggerContent Load()
    {
        using var stream = typeof(KitSwaggerContent).Assembly.GetManifestResourceStream(ResourceName)
                           ?? throw new InvalidOperationException($"Embedded resource '{ResourceName}' is missing.");
        return new KitSwaggerContent(JsonNode.Parse(stream)!.AsObject());
    }
}

public sealed record KitTag(string Name, string? Description);

public sealed class KitOperation
{
    internal KitOperation(JsonObject json, int order)
    {
        Order = order;
        var key = json["key"]!.GetValue<string>();
        var space = key.IndexOf(' ');
        Method = key[..space];
        Path = key[(space + 1)..];
        Tag = json["tag"]!.GetValue<string>();
        Summary = json["summary"]!.GetValue<string>();
        Description = json["description"]?.GetValue<string>();
        Requests = json["requests"]!.AsArray().Select(r => new KitExample(r!.AsObject())).ToList();
        Responses = json["responses"]!.AsArray().Select(r => new KitResponseExample(r!.AsObject())).ToList();
        Headers = json["headers"]!.AsArray()
            .Select(h => new KitHeader(h!["name"]!.GetValue<string>(), h["example"]!.GetValue<string>()))
            .ToList();
    }

    public int Order { get; }

    public string Method { get; }

    /// <summary>Concrete path from the collection, e.g. /fhir/Patient/_search.</summary>
    public string Path { get; }

    public string Tag { get; }

    public string Summary { get; }

    public string? Description { get; }

    public IReadOnlyList<KitExample> Requests { get; }

    public IReadOnlyList<KitResponseExample> Responses { get; }

    public IReadOnlyList<KitHeader> Headers { get; }
}

public sealed class KitExample(JsonObject json)
{
    public string Name { get; } = json["name"]!.GetValue<string>();

    public string? Description { get; } = json["description"]?.GetValue<string>();

    public string? ContentType { get; } = json["contentType"]?.GetValue<string>();

    public JsonNode Body => json["body"]!.DeepClone();
}

public sealed class KitResponseExample(JsonObject json)
{
    public string Status { get; } = json["status"]!.GetValue<string>();

    public string Name { get; } = json["name"]!.GetValue<string>();

    public string? Description { get; } = json["description"]?.GetValue<string>();

    public JsonNode Body => json["body"]!.DeepClone();
}

public sealed record KitHeader(string Name, string Example);
